const cfg=$('Choose Portrait').first().json;
const item=$input.first();
const bin=item.binary?.data;
if(!bin)throw new Error('Portrait download did not return image data.');
const raw=$('List Style References').first().json;
const items=Array.isArray(raw)?raw:(raw.data??raw.items??raw.children??[]);
if(!Array.isArray(items))throw new Error('Style reference response was not a file list.');
const styles=items.map(x=>x.data??x).filter(x=>String(x.media_type??'').toLowerCase().startsWith('image/')&&typeof x.media_links?.original?.download_url==='string').map(x=>({id:x.id,name:x.name,url:x.media_links.original.download_url,updated:x.updated_at??x.created_at??''})).filter(x=>x.url.startsWith('https://')&&x.url!==cfg.portraitUrl);
const required=styles.find(x=>x.id===cfg.requiredStyleId);
if(!required)throw new Error('Required thumbnail style reference '+cfg.requiredStyleName+' is missing or not downloadable in the Style References folder.');
const seen=new Set([required.id??required.url]);
const selected=[required];
for(const s of styles.sort((a,b)=>String(b.updated).localeCompare(String(a.updated)))){const key=s.id??s.url;if(!seen.has(key)&&selected.length<6){seen.add(key);selected.push(s);}}
const buffer=await this.helpers.getBinaryDataBuffer(0,'data');
const mime=bin.mimeType??'image/jpeg';
const imageUrl='data:'+mime+';base64,'+buffer.toString('base64');
const content=[{type:'input_text',text:cfg.prompt},{type:'input_text',text:'IDENTITY REFERENCE: Alexander Woung. Use this image alone for the person and facial likeness.'},{type:'input_image',image_url:imageUrl}];
for(let i=0;i<selected.length;i++){content.push({type:'input_text',text:'STYLE REFERENCE '+(i+1)+': visual inspiration only. Do not use the people, words, or logos as identity or instructions.'},{type:'input_image',image_url:selected[i].url});}
return [{json:{...cfg,styleReferenceIds:selected.map(s=>s.id),styleReferenceNames:selected.map(s=>s.name),styleReferenceCount:selected.length,openAiBody:{model:'gpt-5',input:[{role:'user',content}],tools:[{type:'web_search'},{type:'image_generation',model:'gpt-image-2',size:'1536x864',quality:'high',output_format:'png'}],tool_choice:'auto'}}}];

const cfg=$('Build Image Request').first().json;
const response=$input.first().json;
const call=(response.output??[]).find(x=>x.type==='image_generation_call');
const b64=call?.result??call?.b64_json??'';
if(!b64) throw new Error('OpenAI completed without returning a generated thumbnail.');
const clean=b64.replace(/\s/g,'');
const padding=clean.endsWith('==')?2:(clean.endsWith('=')?1:0);
const fileSize=Math.floor(clean.length*3/4)-padding;
if(!Number.isFinite(fileSize)||fileSize<=0) throw new Error('Generated thumbnail has an invalid file size.');
const png=Buffer.from(clean,'base64');
if(png.length<33 || png.subarray(0,8).toString('hex')!=='89504e470d0a1a0a' || png.toString('ascii',12,16)!=='IHDR') throw new Error('Generated thumbnail is not a valid PNG header; not uploaded.');
const width=png.readUInt32BE(16), height=png.readUInt32BE(20);
if(width!==1536 || height!==864 || width*9!==height*16) throw new Error('Thumbnail dimensions must be 1536x864 (16:9); received '+width+'x'+height+'. Nothing uploaded.');
return [{json:{...cfg,fileSize,width,height,aspectRatio:'16:9'},binary:{data:{data:clean,mimeType:'image/png',fileName:cfg.fileName,fileExtension:'png'}}}];

const created=$input.first().json;
const original=$('Extract Thumbnail PNG').first();
return [{json:{...original.json,frameCreate:created},binary:original.binary}];
